from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test-order-1")
async def test_order_1(file: UploadFile = File(), form: str = Form()):
    return {"file": file.filename, "form": form}

@app.post("/test-order-2")
async def test_order_2(form: str = Form(), file: UploadFile = File()):
    return {"file": file.filename, "form": form}

client = TestClient(app)

def test_order_1():
    response = client.post(
        "/test-order-1",
        data={"form": "test"},
        files={"file": ("test.txt", b"test content")}
    )
    assert response.status_code == 200
    assert response.json() == {"file": "test.txt", "form": "test"}

def test_order_2():
    response = client.post(
        "/test-order-2",
        data={"form": "test"},
        files={"file": ("test.txt", b"test content")}
    )
    assert response.status_code == 200
    assert response.json() == {"file": "test.txt", "form": "test"}

if __name__ == "__main__":
    try:
        test_order_1()
        print("test_order_1 passed")
    except Exception as e:
        print(f"test_order_1 failed: {e}")

    try:
        test_order_2()
        print("test_order_2 passed")
    except Exception as e:
        print(f"test_order_2 failed: {e}")

