from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test-bytes-1")
async def test_bytes_1(file: bytes = File(), form: str = Form()):
    return {"file": file, "form": form}

@app.post("/test-bytes-2")
async def test_bytes_2(form: str = Form(), file: bytes = File()):
    return {"file": file, "form": form}

@app.post("/test-uploadfile-1")
async def test_uploadfile_1(file: UploadFile = File(), form: str = Form()):
    return {"file": file.filename, "form": form}

@app.post("/test-uploadfile-2")
async def test_uploadfile_2(form: str = Form(), file: UploadFile = File()):
    return {"file": file.filename, "form": form}

client = TestClient(app)

def test_bytes_1():
    response = client.post(
        "/test-bytes-1",
        data={"form": "test"},
        files={"file": ("test.txt", b"test content")}
